CREATE OR REPLACE FUNCTION commercial_billing.prevent_parallel_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare state jsonb; item jsonb; items jsonb; player jsonb; pid text; cid text; sport_id text;
begin
 if not exists(select 1 from commercial_billing.definitions) then return new;end if;
 select document into state from credits_sandbox.state limit 1;
 if tg_table_schema='sports_feed' then items:=new.cards;
 else
  if jsonb_typeof(new.document)is distinct from 'object' or new.document->>'playerId'is null then raise exception 'unrecorded inventory denied: trusted player identity required';end if;
  items:=jsonb_build_array(new.document||jsonb_build_object('id',new.id::text));
 end if;
 for item in select value from jsonb_array_elements(items) loop
  pid:=coalesce(item->>'player_id',item->>'playerId'); cid:=coalesce(item->>'id',item->>'card_id');
  player:=state->'economy'->'players'->pid;
  sport_id:=coalesce(to_jsonb(new)->>'sport',player->>'sport');
  if coalesce(sport_id,'unknown')not in('basketball','nba') and item->>'rarity' in('RARE','ELITE','ULTRA_RARE','LEGENDARY','ICON')
   and not coalesce(state->'economy'->'instances','{}'::jsonb)?coalesce(cid,'')
   and not exists(select 1 from commercial_billing.cards c where c.id::text=cid)
   and not exists(select 1 from jsonb_array_elements(coalesce(to_jsonb(old)->'cards','[]')) v where coalesce(v->>'id',v->>'card_id')=cid)
  then raise exception 'Player rarity bound to permanent lifetime ledger; unrecorded inventory denied';end if;
 end loop;
 return new;
end$function$

CREATE OR REPLACE FUNCTION nfl_roster.guard_mint()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare pid text; pos text; sport text; tier text; season text;begin
 if tg_table_schema='credits_sandbox' then
  select p.id,p.identity->>'position',p.sport into pid,pos,sport from credits_sandbox.card_definitions d join credits_sandbox.permanent_players p on p.id=d.player_id where d.id=new.definition;
 else
  select p.id::text,p.position,p.sport,e.tier,e.season into pid,pos,sport,tier,season from beta_fantasy.editions e join beta_fantasy.players p on p.id=e.player_id where e.id=new.edition_id;
  if sport='nfl' and tier='CORE' and not new.tradeable then
   if not season_catalogue.can_issue(sport,season,pid::uuid,'free_weekly') then raise exception 'Approved season catalogue and source-use rights required';end if;
   return new;
  end if;
 end if;
 if sport='nfl' and not nfl_roster.can_issue(pid,pos) then raise exception 'Official NFL roster eligibility required; no cards issued';end if;
 return new;
end$function$

